    beats = {
        { id = "egg", at = 15, title = "The egg",
            text = "I hatched under a hedge from a plain buff egg, one of four. I was brown. Speckled, stubby and brown. I tell you this in the strictest confidence, and I shall deny everything if asked." },
        { id = "plain_years", at = 40, title = "The plain years",
            text = "A peacock waits three years for a full train. Three years of looking like everybody else. I practised fanning anyway, with nothing to fan, behind the potting shed where nobody could laugh." },
        { id = "first_eye", at = 80, title = "The first eye",
            text = "My first proper feather came in my third spring. One long plume, one eye, green and bronze. I turned in circles for a whole day trying to see the eye. I have been turning to look ever since." },
        { id = "lawn", at = 140, title = "The great lawn",
            text = "I lived then at a large house with a lawn and visitors on Sundays. I fanned, they gasped. I fanned again, they gasped again. I thought: so this is love. They always left by five o'clock." },
        { id = "fall", at = 220, title = "The first fall",
            text = "Nobody had told me the train comes out. One morning in late summer there were feathers on the grass. Mine. More each day. I truly thought I was finished, and that the gasping had been all there was of me." },
        { id = "yew", at = 320, title = "Behind the yew",
            text = "I hid behind a yew hedge that whole autumn. The visitors asked where the peacock was. I stood eight steps away, plain from every side, and nobody knew me. I learned then how little of me they had ever looked at." },
        { id = "feather", at = 450, title = "The kept feather",
            text = "A small girl found one of my fallen feathers that autumn. She did not gasp. She held my feather against her coat and carried the prize home in both hands. I have wondered ever since where that eye of mine is looking now." },
        { id = "spring", at = 600, title = "Spring again",
            text = "By spring the train was back, every eye in place. I was so relieved that I called for two days. The gasping came back too. Only now I knew what I looked like in November, and the gasps sounded thinner." },
        { id = "gate", at = 800, title = "The open gate",
            text = "One evening the gate stood open and I walked out. I cannot tell you why. A star does not leave a full house. I suppose I wanted to find out whether anyone would care for me in the wrong season." },
        { id = "garden", at = 1050, title = "No pose prepared",
            text = "I arrived here in autumn, of all times. No train, mud to the knee, hardly an entrance. You looked up from a book and said hello, as if I were worth greeting exactly as I stood. I had no pose prepared for that." },
        { id = "eyes", at = 1400, title = "The eyes",
            text = "Count the eyes on a full train and you will pass a hundred. I grew them so the world would look at me. {total} pages you have read beside me, glancing up between them, and one of those glances outweighs every Sunday on the lawn." },
        { id = "folded", at = 1800, title = "Folded",
            text = "The train will fall again this year, and grow again, and I am no longer afraid of the falling. I fan for the garden because I love a show. For you I fold everything away and sit close, plain at the back, while you turn your page. Nobody else has been given this performance. I call the piece being known." },
    },
}
